patch:
diff --git a/repro/no-unused-expressions-es3-directive.js b/repro/no-unused-expressions-es3-directive.js
new file mode 100644
index 0000000..6200e8b
--- /dev/null
+++ b/repro/no-unused-expressions-es3-directive.js
@@ -0,0 +1,22 @@
+"use strict";
+
+// Repro for: no-unused-expressions reports 'use strict' (9.25.0).
+// Usage: node repro/no-unused-expressions-es3-directive.js [path/to/eslint/lib/api]
+const path = require("node:path");
+const { Linter } = require(process.argv[2] || path.join(__dirname, "../lib/api"));
+
+const code = "'use strict';\nfunction f() { 'use strict'; return 1; }\nf();\n";
+const linter = new Linter({ configType: "flat" });
+let failed = false;
+
+for (const ecmaVersion of [3, 5, 2015]) {
+	const messages = linter.verify(
+		code,
+		[{ languageOptions: { ecmaVersion, sourceType: "script" }, rules: { "no-unused-expressions": "error" } }],
+		"x.js",
+	);
+	const bad = messages.filter(m => m.ruleId === "no-unused-expressions" || m.fatal);
+	console.log(`ESLint ${linter.version}, ecmaVersion ${ecmaVersion}: ${bad.length ? bad.map(m => `${m.line}:${m.column} ${m.message}`).join("; ") : "no errors"}`);
+	if (bad.length) failed = true;
+}
+process.exitCode = failed ? 1 : 0;
